chart.options:
chart: {
  type: 'unit',
  height: 470,
  animations: {
    enabled: true,
    speed: 900,
  },
},
labels: ['Engineering', 'Health', 'Business', 'Arts and humanities'],
colors: ['#1565C0', '#00A96E', '#F2994A', '#D64545'],
plotOptions: {
  unit: {
    layout: 'custom',
    // One of the shapes in apexcharts/unit-shapes.
    positions: 'mortarboard',
    transition: 'flow',
    unitValue: 20,
    clusterLabels: {
      // Outer labels: each band is named in the margin with a leader line to its
      // own dots, so the crowd reads without a legend.
      external: {
        show: true,
      },
    },
  },
},
legend: {
  show: false,
},
